import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

import java.util.List;
import java.util.Optional;

public interface InterestRepository extends JpaRepository<Interest, Long> {
    boolean existsByUserAndProductColor(User user, ProductColor productColor);

    Optional<Interest> findByUserAndProductColor(User user, ProductColor productColor);

    List<Interest> findAllByUserId(Long userId);

    // 상품 색상을 관심 등록한 활성 회원 (제외 대상 회원 제외)
    @Query("SELECT i FROM Interest i JOIN FETCH i.user u " +
            "WHERE i.productColor = :productColor AND u.isActive = true AND u.id <> :excludedUserId")
    List<Interest> findActiveInterestsByProductColorExcludingUser(@Param("productColor") ProductColor productColor,
                                                                  @Param("excludedUserId") Long excludedUserId);
}

