private void notifyInterestedUsers(SaleBid saleBid, User seller, ProductSize productSize) {
    String productName = productSize.getProductColor().getProduct().getName();
    String message = String.format("관심 상품 [%s] 사이즈 %s에 새 판매 입찰이 등록되었습니다. 판매 희망가 %,d원",
            productName, productSize.getSize(), saleBid.getBidPrice());

    List<Interest> interests = interestRepository.findActiveInterestsByProductColorExcludingUser(
            productSize.getProductColor(), seller.getId());
    for (Interest interest : interests) {
        notificationCommandService.createNotification(
                interest.getUser().getId(),
                NotificationCategory.SHOPPING,
                NotificationType.FAVORITE,
                message
        );
    }
}

